#!/usr/bin/env python3
"""Small original SVG props, in the existing SnowPlay palette. No downloaded artwork."""
from pathlib import Path
import json,math,struct,wave
root=Path(__file__).resolve().parents[1]/'Sources/SnowPlay/Resources/SnowPlayAssets'
folder=root/'World';m=json.loads((folder/'manifest.json').read_text())
art={
'story_ladder':(64,100,'<path d="M14 95L25 6M50 95L39 6" stroke="#885533" stroke-width="8" stroke-linecap="round"/><path d="M17 77H47M19 59H45M21 41H43M23 23H41" stroke="#d7ae71" stroke-width="5" stroke-linecap="round"/><path d="M25 6L14 95M39 6L50 95" stroke="#edca90" stroke-width="2" stroke-linecap="round"/>'),
'story_toolbox':(48,36,'<path d="M16 13V6Q24 1 32 6V13" fill="none" stroke="#38617c" stroke-width="4"/><rect x="3" y="12" width="42" height="21" rx="6" fill="#e77766" stroke="#ffc6a0" stroke-width="2"/><path d="M4 20H44" stroke="#a54d57" stroke-width="2"/><rect x="21" y="16" width="6" height="10" rx="2" fill="#ffe3a2"/>'),
'story_screwdriver':(12,40,'<path d="M6 3V25" stroke="#d5e6ec" stroke-width="4" stroke-linecap="round"/><rect x="2" y="23" width="8" height="15" rx="4" fill="#ed8a65"/><path d="M5 26V34" stroke="#ffe4aa" stroke-width="2"/>'),
'story_toolbelt':(48,22,'<path d="M3 6H45V14H3Z" fill="#81553e"/><rect x="6" y="7" width="15" height="13" rx="4" fill="#c78c59"/><rect x="29" y="6" width="12" height="14" rx="3" fill="#dfad72"/><path d="M33 2V12" stroke="#e1edf7" stroke-width="3"/>'),
'story_bulb':(24,34,'<path d="M9 5H15V12H9Z" fill="#557d6a"/><path d="M8 12Q2 21 7 27Q12 32 17 27Q22 21 16 12Z" fill="#ffe08c" stroke="#fff4cf" stroke-width="2"/><path d="M9 17L11 24L15 18" fill="none" stroke="#fff" stroke-width="2"/>'),
'story_carrot':(44,18,'<path d="M8 4Q17 2 40 10Q18 17 8 14Z" fill="#f5a057" stroke="#ffd19a" stroke-width="2"/><path d="M8 9L2 3M8 9L1 12" stroke="#67b58c" stroke-width="3" stroke-linecap="round"/>'),
'story_party_hat':(36,42,'<path d="M5 34L17 4Q20 2 21 6L32 34Z" fill="#89cdd6" stroke="#d2f4e9" stroke-width="2"/><path d="M10 23L25 16M8 30L28 23" stroke="#f9dba0" stroke-width="4"/><ellipse cx="18" cy="35" rx="15" ry="4" fill="#f0f9ff"/><circle cx="18" cy="4" r="3" fill="#ffedb2"/>'),
'story_scarf':(45,28,'<path d="M3 4Q22 12 41 4L40 12Q23 20 3 12Z" fill="#ef91ab" stroke="#ffd6dc" stroke-width="2"/><path d="M28 12L40 12L37 26H27Z" fill="#ef91ab"/><path d="M30 17H38M29 22H37" stroke="#ffe0c7" stroke-width="2"/>'),
'story_star':(32,32,'<path d="M16 2L20 11L30 12L23 19L25 29L16 24L7 29L9 19L2 12L12 11Z" fill="#ffe2a0" stroke="#fff2cf" stroke-width="2"/>'),
'story_gift_sack':(38,45,'<path d="M14 11L9 3L27 3L23 11Q39 25 33 37Q18 47 4 35Q0 23 14 11Z" fill="#b77a60" stroke="#ebbc91" stroke-width="2"/><path d="M12 12H26" stroke="#f5dcaa" stroke-width="3"/><path d="M24 16Q30 20 30 27" stroke="#dab28a" stroke-width="2" fill="none"/>'),
'story_reindeer':(76,54,'<path d="M13 34Q0 24 6 20" fill="none" stroke="#bf895e" stroke-width="5"/><ellipse cx="34" cy="32" rx="23" ry="14" fill="#bf895e" stroke="#f1cd9b" stroke-width="2"/><path d="M49 29L53 12L67 14L67 34Z" fill="#bf895e"/><ellipse cx="62" cy="15" rx="12" ry="10" fill="#c99a6a"/><ellipse cx="68" cy="18" rx="8" ry="5" fill="#edc59a"/><circle cx="73" cy="17" r="3" fill="#e99087"/><circle cx="62" cy="11" r="2" fill="#35465d"/><path d="M56 8L51 1M56 6L60 1M51 4L46 2" stroke="#e4c39b" stroke-width="3" stroke-linecap="round"/><path d="M50 29L64 32" stroke="#f4a6a3" stroke-width="4"/>'),
'story_reindeer_leg':(10,25,'<path d="M3 2L6 19" stroke="#b67e56" stroke-width="6" stroke-linecap="round"/><path d="M4 20H9" stroke="#655a59" stroke-width="6" stroke-linecap="round"/>'),
}
for color,fill in [('red','#ef8e99'),('blue','#8cbbdf'),('green','#8bc8ad')]:
 art['story_present_'+color]=(38,40,f'<rect x="4" y="13" width="30" height="24" rx="4" fill="{fill}" stroke="#eaf8ed" stroke-width="2"/><rect x="2" y="9" width="34" height="8" rx="3" fill="{fill}" stroke="#f9e9b9" stroke-width="2"/><path d="M19 10V37M4 24H34" stroke="#f9e2a2" stroke-width="4"/><path d="M19 10Q3 10 9 3Q15 0 19 10Q21 0 28 3Q34 10 19 10Z" fill="#f9e2a2"/>')
ids=set(art)
m['assets']=[a for a in m['assets'] if a['id'] not in ids]
for id,(w,h,body) in art.items():
 (folder/(id+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{body}</svg>\n')
 m['assets'].append({'id':id,'category':'Christmas','svg':'World/'+id+'.svg','preview':'Prepared/'+id+'@2x.png','viewBox':[0,0,w,h],'size':{'width':w,'height':h},'anchor':{'x':.5,'y':.5},'components':[],'description':'Original Christmas Stories prop, SnowPlay palette; generated by Scripts/generate-story-assets.py'})
m['asset_count']=len(m['assets']);(folder/'manifest.json').write_text(json.dumps(m,indent=2,ensure_ascii=False)+'\n')
# A quiet optional chime. Disabled by default; generated once, never synthesized per frame.
with wave.open(str(root/'World/story_chime.wav'),'wb') as wav:
 wav.setparams((1,2,22050,0,'NONE','not compressed'))
 samples=[]
 for i in range(15435):
  t=i/22050;v=sum(math.sin(2*math.pi*f*t)*max(0,1-t/.7)**3 for f in [523.25,659.25,783.99])/3
  samples.append(struct.pack('<h',int(v*1600*min(1,t/.02))))
 wav.writeframes(b''.join(samples))
print('Created',len(art),'small vector props and an optional quiet chime')
